        AttemptCmd::Submit {
            work,
            attempt,
            summary,
        } => submit(ctx, &work, &attempt, &summary),
        AttemptCmd::Fail {
            work,
            attempt,
            reason,
        } => fail(ctx, &work, &attempt, &reason),
