fn replace(ctx: &Ctx, work: &str, attempt: &str, reason: &str) -> Outcome {
    let reason = match crate::cli::parse_text_arg(reason) {
        Ok(value) => value,
        Err(message) => return output::param_error(message),
    };
    let attempt = match AttemptId::parse(attempt) {
