/// 按节点的 `inputs[]` 逐条绑定。
///
/// - `Start { key }`：取 `state.inputs[key]`；观察摘要不符 `Error::ArtifactModified`。
/// - `Resource { path }`：路径 `state.workbook_dir().join(path)`；观察必须存在且摘要是它的摘要（首次绑定时以观察为准记录）。
/// - `EngineStats`：不看观察，这里只记下「要」，绑定由 `decide_begin` 在推进状态后用
///   `engine_stats_artifact` 回填并追加 `Effect::WriteFile`（口径含本次 Attempt，D-29）。
/// - `Node { node, output }`：取 `latest_succeeded_of(node)` 的 `outputs[output]`；
///   没有时 `required` 为真报 `Error::InputUnavailable`，否则绑 `None`；
///   有时观察摘要必须等于记录，否则 `Error::ArtifactModified`。
///
/// 返回逐条绑定（`EngineStats` 条目为占位 `None`）与「是否有 engine.stats 输入」。
type BoundInputs = BTreeMap<String, Option<ArtifactRef>>;

fn bind_inputs(
    state: &WorkState,
    graph: &Graph,
    node: &NodeId,
    observed_inputs: &BTreeMap<String, Option<ObservedFile>>,
) -> Result<(BoundInputs, bool)> {
    let def = graph.node(node).ok_or_else(|| Error::InvalidRequest {
        reason: format!("节点 {node} 不在图里"),
    })?;
    let mut bound = BTreeMap::new();
    // 是否有 engine.stats 输入。它的绑定由 `decide_begin` 在推进状态后回填（口径含本次 Attempt）。
    let mut wants_stats = false;
    for decl in &def.inputs {
        let observed = observed_inputs.get(&decl.name).and_then(|o| o.as_ref());
        let artifact = match &decl.from {
            InputSource::Start { key } => {
                let want = state.inputs.get(key).ok_or_else(|| Error::InputMissing {
                    missing: vec![key.clone()],
                    extra: Vec::new(),
                })?;
                Some(bind_frozen_input(&decl.name, want, observed)?)
            }
            InputSource::Resource { path } => {
                let full = state.workbook_dir().join(path);
                let obs = observed.ok_or_else(|| Error::ArtifactModified {
                    input: decl.name.clone(),
                    path: full.as_str().to_string(),
                })?;
                Some(ArtifactRef {
                    path: full,
                    sha256: obs.sha256.clone(),
                    bytes: obs.bytes,
                })
            }
            InputSource::EngineStats => {
                // 占位，由 decide_begin 在推进状态后统一回填。
                wants_stats = true;
                None
            }
            InputSource::Node { node: src, output } => match state
                .latest_succeeded_of(src)
                .and_then(|a| a.outputs.get(output))
            {
                Some(want) => Some(bind_frozen_input(&decl.name, want, observed)?),
                None => {
                    if decl.required {
                        return Err(Error::InputUnavailable {
                            input: decl.name.clone(),
                            node: src.clone(),
                        });
                    }
                    None
                }
            },
        };
        bound.insert(decl.name.clone(), artifact);
    }
    Ok((bound, wants_stats))
}

fn bind_frozen_input(
    name: &str,
    reference: &ArtifactRef,
    observed: Option<&ObservedFile>,
) -> Result<ArtifactRef> {
    if !observed.is_some_and(|file| file.matches(reference)) {
        return Err(Error::ArtifactModified {
            input: name.to_string(),
            path: reference.path.as_str().to_string(),
        });
    }
    Ok(reference.clone())
}

/// `attempt submit` 第 1 到 6 步。
///
/// 1. Attempt 必须 `Running`，否则 `Error::AttemptNotRunning`。
/// 2. `summary` ≤ 4096 字节，否则 `Error::SummaryTooLong`。
/// 3. `check_outputs`。任一失败整体 `Err`，状态不变。
/// 4. 记录输出 `ArtifactRef`，`status = Succeeded`，`ended_at = ctx.now`。
/// 5. `status_after_success` 定 Work 状态（含 `gate`）。
/// 6. 回复 `Reply::AttemptSubmitted`；效果 `SealOutputs`、`RefreshStatusCard`。
fn decide_submit(
    state: &WorkState,
    graph: &Graph,
    attempt: &AttemptId,
    summary: &str,
    observed_outputs: &BTreeMap<String, Option<ObservedFile>>,
    ctx: &Context,
) -> Result<Decision> {
    let not_running = || Error::AttemptNotRunning {
        attempt: attempt.clone(),
    };
    let prev = state.attempt(attempt).ok_or_else(not_running)?;
    if prev.status != AttemptStatus::Running {
        return Err(not_running());
    }
    // 协议 attempt submit 第 2 步：超限报 `SUMMARY_TOO_LONG`，不是通用的 `TEXT_TOO_LONG`。
    let summary_text = Summary::new(summary, "summary").map_err(|_| Error::SummaryTooLong {
        max: Summary::max_bytes(),
        actual: summary.len(),
    })?;
    let sealed = check_outputs(state, graph, attempt, observed_outputs)?;

    let mut new_state = state.clone();
    if let Some(a) = new_state.attempt_mut(attempt) {
        a.status = AttemptStatus::Succeeded;
        a.outputs = sealed.clone();
        a.summary = Some(summary_text);
        a.ended_at = Some(ctx.now.clone());
    }
    new_state.status = status_after_success(&new_state, graph, true);
    // 累计受阻在发生时记录（GF-29）：gate 阻断与 no_legal_edge 各计一次。
    if matches!(
        new_state.status,
        WorkStatus::Blocked(BlockedReason::Gate | BlockedReason::NoLegalEdge)
    ) {
        increment_blocked_count(&mut new_state)?;
    }
    new_state.updated_at = ctx.now.clone();

    Ok(Decision {
        state: new_state,
        effects: vec![
            Effect::SealOutputs {
                paths: sealed.values().map(|r| r.path.clone()).collect(),
            },
            Effect::RefreshStatusCard,
        ],
        reply: Reply::AttemptSubmitted {
            attempt: attempt.clone(),
            outputs: sealed,
        },
    })
}

/// 对照节点 `outputs[]` 校验观察：`required` 且缺 → `Error::OutputMissing`；
/// 超 `max_bytes` → `Error::OutputTooLarge`；可选且缺 → 跳过。返回要封存的引用。
fn check_outputs(
    state: &WorkState,
    graph: &Graph,
    attempt: &AttemptId,
    observed_outputs: &BTreeMap<String, Option<ObservedFile>>,
) -> Result<BTreeMap<String, ArtifactRef>> {
    let def = graph
        .node(&attempt.node)
        .ok_or_else(|| Error::InvalidRequest {
            reason: format!("节点 {} 不在图里", attempt.node),
        })?;
    let mut sealed = BTreeMap::new();
    for decl in &def.outputs {
        match observed_outputs.get(&decl.name).and_then(|o| o.as_ref()) {
            Some(obs) => {
                if obs.bytes > decl.max_bytes {
                    return Err(Error::OutputTooLarge {
                        output: decl.name.clone(),
                        max_bytes: decl.max_bytes,
                        actual: obs.bytes,
                    });
                }
                sealed.insert(decl.name.clone(), obs.clone().into_ref());
            }
            None => {
                if decl.required {
                    let path =
                        crate::work::layout::output_path(&state.attempt_dir(attempt), &decl.path);
                    return Err(Error::OutputMissing {
                        output: decl.name.clone(),
                        path: path.as_str().to_string(),
                    });
                }
            }
        }
    }
    Ok(sealed)
}

/// 节点 Attempt 成功（或门槛刚批准）后 Work 的状态，按协议 `attempt submit` 第 5 步的顺序：
/// `consider_gate && node.gate` → `Blocked(Gate)`；无出边 → `Succeeded`；
/// 每条出边目标都 `visits >= max_visits` → `Blocked(NoLegalEdge)`；否则 `Active`。
fn success_status_at(
    graph: &Graph,
        Some(
            access
                .load_request(request_id, &metadata)
                .map_err(|failure| failure.into_pending(request_id))?,
        )
    } else {
        None
    };
    let committed = current.is_some();
    let current_original = current.as_ref().map(|request| request.original.clone());
    for pending_id in store.unpublished_request_ids()? {
        let loaded = if pending_id == request_id {
            match current.take() {
                Some(request) => Ok(request),
                None => request_metadata(store, &pending_id)
                    .map_err(RequestLoadError::from)
                    .and_then(|metadata| access.load_request(&pending_id, &metadata)),
            }
        } else {
            request_metadata(store, &pending_id)
                .map_err(RequestLoadError::from)
                .and_then(|metadata| access.load_request(&pending_id, &metadata))
        };
        let request = match loaded {
            Ok(request) => request,
            Err(failure) => {
                let blocker = failure.into_pending(&pending_id);
                if pending_id == request_id {
                    return Err(blocker);
                }
                return Err(blocked_by_pending(
                    request_id,
                    committed,
                    &pending_id,
                    current_original.clone(),
                    blocker,
                ));
            }
        };
        if pending_id == request_id && request.row.intent_hash != intent_hash {
            return Err(Error::RequestConflict {
                request_id: request_id.to_string(),
            });
        }
        if let Err(error) = finish_checked_request(
            home,
            store,
            lock,
            CheckedRequestEffects {
                request_id: &pending_id,
                request: &request,
            },
            None,
            access,
        ) {
            if pending_id == request_id {
                return Err(error);
            }
            return Err(blocked_by_pending(
                request_id,
                committed,
                &pending_id,
                current_original.clone(),
                error,
            ));
        }
    }
    if !committed {
        crate::pending::prepare_new_request(home, store, lock, request_id)?;
    }
    Ok(())
}

/// 完成一个已提交请求。快照校验成功后，效果失败保留已核原响应。
pub(crate) fn finish_request(
    home: &Home,
    store: &Store,
    lock: &HomeLock,
    request_id: &str,
    observed_outputs: Option<&BTreeMap<String, SafeFile>>,
    verify_published: bool,
    access: &dyn RecoveryAccess,
) -> Result<()> {
    let metadata = request_metadata(store, request_id)
        .map_err(|cause| own_pending(request_id, None, cause))?;
    let request = access
        .load_request(request_id, &metadata)
        .map_err(|failure| failure.into_pending(request_id))?;
    if request.row.published && !verify_published {
        return Ok(());
    }
    finish_checked_request(
        home,
        store,
        lock,
        CheckedRequestEffects {
            request_id,
            request: &request,
        },
        observed_outputs,
        access,
    )
}

/// 调用者在同一写锁内核过快照与整组效果；复用已装入的上下文。
pub(crate) fn finish_checked_request(
    home: &Home,
    store: &Store,
    lock: &HomeLock,
    checked: CheckedRequestEffects<'_>,
    observed_outputs: Option<&BTreeMap<String, SafeFile>>,
    access: &dyn RecoveryAccess,
) -> Result<()> {
    let CheckedRequestEffects {
        request_id,
        request,
    } = checked;
    let original = Some(request.original.clone());
    let complete = !request.row.published;
    let execution = match observed_outputs {
        Some(observed) if complete => {
            execute_with_observed_outputs(home, lock, &request.effects, true, Some(observed))
        }
        _ => execute(home, lock, &request.effects, complete),
    };
    execution.map_err(|cause| own_pending(request_id, original.clone(), cause))?;
    if complete {
        access
            .refresh_cards(&request.effects, lock)
            .map_err(|cause| own_pending(request_id, original.clone(), cause))?;
        store
            .mark_published(request_id)
            .map_err(|cause| own_pending(request_id, original, cause))?;
        crate::failpoint::maybe_exit("request_published_before_cleanup");
    }
    Ok(())
}

pub(crate) fn own_pending(request_id: &str, original: Option<String>, cause: Error) -> Error {
    Error::effect_pending(true, request_id.to_string(), None, &cause, original, None)
}

fn blocked_by_pending(
    request_id: &str,
    committed: bool,
    pending_request_id: &str,
    original: Option<String>,
    blocker: Error,
) -> Error {
    let (cause, cause_detail, pending_original) = match blocker {
        Error::EffectPending {
            cause,
            cause_detail,
            original,
            pending_original,
            ..
        } => (cause, cause_detail, pending_original.or(original)),
        other => (other.code(), other.to_string(), None),
    };
    Error::EffectPending {
        committed,
        request_id: request_id.to_string(),
        pending_request_id: Some(pending_request_id.to_string()),
